# OWNER: (name)   ROLE: verifier   NEEDS: all results   WRITES: results["verification"] (and may correct results)
"""Cross-checks before the calculator: what is safe to bid, what must be omitted, and whether no_bid is justified.

results["verification"] = {"decision": "bid" | "no_bid", "omit": ["<pos>", ...], "issues": ["...", ...]}
Plain code: it only compares what the analyzers wrote; it never reads the websites or asks a model.
"""
from swarm import Agent, Phase, register
from swarm.facts import brief_facts, number


@register
class EvidenceVerifier(Agent):
    phase = Phase.VERIFY

    async def run(self) -> None:
        board = self.ctx.board
        facts = await brief_facts(self.ctx)
        result = verify(facts, board.get("quantities") or {}, board.get("requirements") or {},
                        board.get("materials") or {}, board.get("discount") or {})
        await board.set("verification", result)
        self.log.info("decision %s, omit %s, issues %s", result["decision"], result["omit"], result["issues"])


def verify(facts: dict, quantities: dict, requirements: dict, materials: dict, discount: dict) -> dict:
    issues, omit = [], []
    if not facts.get("tender_reference"):
        issues.append("no tender reference from the brief")
    positions = quantities.get("positions") or {}
    if not positions:
        issues.append("no tender positions")
    by_req = requirements.get("by_position") or {}
    by_mat = materials.get("by_position") or {}
    for pos, info in positions.items():
        problems = []
        if number(info.get("quantity")) is None:
            problems.append("quantity")
        if pos not in by_req:
            problems.append("requirement")
        elif (info.get("unit") or "").casefold().startswith("satz") and not by_req[pos].get("pieces_per_set"):
            problems.append("pieces per set")
        if not by_mat.get(pos):
            problems.append("material")
        if problems:
            omit.append(pos)
            issues.append(f"{pos}: missing {', '.join(problems)}")
    no_match = [p for p in materials.get("no_match") or [] if p in positions]
    decision = "no_bid" if no_match else "bid"
    if no_match:
        issues.append(f"no active matching material for {no_match}: no_bid")
    if number(discount.get("percent")) is None:
        issues.append("discount percent unreadable: 0 %")
    return {"decision": decision, "omit": sorted(set(omit)), "issues": issues}

# OWNER: (name)   ROLE: calculator (plain code, no model)   NEEDS: quantities, requirements, materials, discount,
#                 authority, verification   WRITES: results["bid"] (the answer object, see swarm.bidmath.answer)
"""Deterministic pricing, lead time and allocations per the brief's rules, on top of swarm.bidmath.

A position that cannot be priced is omitted (partial submission) and named in `notes`. A breakdown field whose
inputs were not found is left out of the entry (blank = unanswered) instead of being reported as a wrong 0.
"""
from swarm import Agent, Phase, register
from swarm.bidmath import (BASE_AND_SURCHARGE, BASE_ONLY, NO_DISCOUNT, ZERO, Band, Bid, D, PositionFacts, RateWindow,
                           Scale, allocate_cents, answer, base_unit_price_eur, carton_cost, final_pieces,
                           lead_time_weeks, marginal_credit, order_discount, plain, rate_on, undiscounted_net)
from swarm.facts import brief_facts, iso_date, number, scenario_date, token

CLAUSES = {"base_only": BASE_ONLY, "base_and_surcharge": BASE_AND_SURCHARGE, "none": NO_DISCOUNT}


@register
class BidCalculator(Agent):
    """Deterministic pricing/lead time/allocation per the brief's rules. Keep rounding rules in tested pure functions."""
    phase = Phase.COMPUTE

    async def run(self) -> None:
        board = self.ctx.board
        facts = await brief_facts(self.ctx)
        bid = compute(facts, board.get("quantities") or {}, board.get("requirements") or {},
                      board.get("materials") or {}, board.get("discount") or {}, board.get("authority") or {},
                      board.get("verification") or {})
        await board.set("bid", bid)
        self.log.info("bid: %s, %d positions, discount %s, total %s; %s", bid["decision"], len(bid["positions"]),
                      bid["discount_percent"], bid["total_net"], bid["notes"])


def _data(authority: dict, topic: str) -> dict:
    return (authority.get(topic) or {}).get("data") or {}


def _lookup(table: dict, key):
    """A keyed value whatever the key's spacing/case on the page ('VP-1134' == 'vp 1134')."""
    if not key or not isinstance(table, dict):
        return None
    return next((v for k, v in table.items() if token(k) == token(key)), None)


def condition_on(conditions: list[dict], material: str, on) -> dict | None:
    """Rule 4: the material's price condition valid on the scenario date, both endpoints inclusive."""
    valid = [c for c in conditions if token(c.get("material")) == token(material)
             and (iso_date(c.get("valid_from")) is None or on is None or iso_date(c["valid_from"]) <= on)
             and (iso_date(c.get("valid_to")) is None or on is None or on <= iso_date(c["valid_to"]))]
    return max(valid, key=lambda c: iso_date(c.get("valid_from")) or iso_date("1900-01-01")) if valid else None


def compute(facts, quantities, requirements, materials, discount, authority, verification) -> dict:
    reference = plain(facts.get("tender_reference"))
    on = scenario_date(facts)
    if verification.get("decision") == "no_bid":
        return answer(Bid(tender_reference=reference, decision="no_bid", notes="no active matching material"))

    positions = quantities.get("positions") or {}
    keys = quantities.get("keys") or {}
    by_req = requirements.get("by_position") or {}
    by_mat = materials.get("by_position") or {}
    catalog = materials.get("catalog") or {}
    conditions = materials.get("conditions") or []
    omit = set(verification.get("omit") or [])
    skipped: dict[str, str] = {}

    # pieces for every position with a material (pooled demand counts them all, rule 15)
    pieces: dict[str, int] = {}
    for pos, info in positions.items():
        try:
            pieces[pos] = final_pieces(info.get("quantity"), info.get("unit") or "",
                                       (by_req.get(pos) or {}).get("pieces_per_set"))
        except Exception as error:  # noqa: BLE001
            skipped[pos] = f"quantity: {error}"
    pooled: dict[str, int] = {}
    for pos, n in pieces.items():
        if by_mat.get(pos):
            pooled[by_mat[pos]] = pooled.get(by_mat[pos], 0) + n

    fx = _data(authority, "fx").get("rates") or {}
    metal = _data(authority, "metal_index").get("codes") or {}
    clauses = _data(authority, "clauses").get("groups") or {}
    tariffs = _data(authority, "packaging").get("tariffs") or {}
    commitments = _data(authority, "commitments").get("commitments") or {}
    pools = _data(authority, "setup_pool").get("pools") or {}
    bands = _data(authority, "bonus").get("bands") or []

    built: dict[str, PositionFacts] = {}
    unknown_fields: dict[str, set] = {}
    for pos in positions:
        material = by_mat.get(pos)
        if pos in omit or pos in skipped or not material:
            skipped.setdefault(pos, "omitted by verification" if pos in omit else "no material")
            continue
        m, n, k = catalog.get(material) or {}, pieces[pos], keys.get(pos) or {}
        cond = condition_on(conditions, material, on)
        if cond is None or not cond.get("scales"):
            skipped[pos] = "no valid price condition"
            continue
        currency = plain(cond.get("currency") or "EUR").upper()
        eur_per_unit = D(1) if currency in ("EUR", "€") else number(_lookup(fx, cond.get("fx_key")) or _lookup(fx, currency))
        if eur_per_unit is None:
            skipped[pos] = f"no FX rate for {currency}"
            continue
        try:
            base = base_unit_price_eur([Scale(int(number(s["min_quantity"]) or 0), number(s["price"]))
                                        for s in cond["scales"]], n, int(number(cond.get("price_unit")) or 1),
                                       eur_per_unit)
        except Exception as error:  # noqa: BLE001
            skipped[pos] = f"price: {error}"
            continue
        unknown = set()

        surcharge = ZERO
        code = cond.get("metal_index_code")
        if code:
            windows = [RateWindow(number(w.get("rate")), iso_date(w.get("valid_from")), iso_date(w.get("valid_to")))
                       for w in (_lookup(metal, code) or []) if number(w.get("rate")) is not None]
            mass = number(m.get("surcharge_mass_kg"))
            try:
                surcharge = D(mass) * rate_on(windows, on) * eur_per_unit if mass is not None and on else None
            except ValueError:
                surcharge = None
            if surcharge is None:
                surcharge, unknown = ZERO, unknown | {"surcharge_per_unit"}

        cartons = ZERO
        if k.get("packaging_tariff"):
            price, size = number(_lookup(tariffs, k["packaging_tariff"])), number(m.get("pieces_per_carton"))
            if price is None or not size:
                unknown.add("packaging_per_unit")
            else:
                cartons = carton_cost(n, int(size), price)

        lead = None
        commitment = _lookup(commitments, k.get("delivery_commitment")) if k.get("delivery_commitment") else None
        if commitment and token(commitment.get("material")) == token(material) \
                and number(commitment.get("weeks")) is not None and number(commitment.get("ceiling_pieces")) is not None:
            lead = lead_time_weeks(0, pooled[material], 0, 0, int(number(commitment["weeks"])),
                                   int(number(commitment["ceiling_pieces"])))
            if pooled[material] > int(number(commitment["ceiling_pieces"])):
                lead = None      # ceiling exceeded: shared-stock rule below
        if lead is None:
            stock, s_weeks, p_weeks = (number(m.get(x)) for x in ("stock_pieces", "stock_weeks", "production_weeks"))
            if stock is None or s_weeks is None or p_weeks is None:
                skipped[pos] = "no stock / lead times"
                continue
            lead = lead_time_weeks(int(stock), pooled[material], int(s_weeks), int(p_weeks))

        built[pos] = PositionFacts(
            position=pos, material_number=material, pieces=n, base_unit_price=base, lead_time_weeks=int(lead),
            surcharge_per_piece=surcharge, setup_fee=D(number(cond.get("setup_fee")) or 0), carton_cost=cartons,
            clause=CLAUSES.get(str(_lookup(clauses, k.get("konditionsgruppe")) or "").strip(), BASE_ONLY)
            if k.get("konditionsgruppe") else BASE_ONLY)
        unknown_fields[pos] = unknown

    # shared setup pools (rule 25): one fee per pool, allocated by pieces x allocation mass
    members: dict[str, list[str]] = {}
    for pos in built:
        pool = (keys.get(pos) or {}).get("setup_pool")
        if pool:
            members.setdefault(str(pool), []).append(pos)
    for pool, group in members.items():
        spec = _lookup(pools, pool) or (next(iter(pools.values())) if len(pools) == 1 else None)
        fee = number((spec or {}).get("fee_eur"))
        weights = {p: D(built[p].pieces) * D(number(catalog[built[p].material_number].get("allocation_mass")) or 0)
                   for p in group}
        if fee is None or not any(weights.values()):
            for p in group:
                unknown_fields[p].add("surcharge_per_unit")
            continue
        for p, share in allocate_cents(fee, weights).items():
            built[p].shared_setup = share

    # project bonus (rule 26): marginal bands on the eligible undiscounted goods total, allocated in cents
    eligible = {p: D(f.pieces) * f.base_unit_price for p, f in built.items()
                if (keys.get(p) or {}).get("project_bonus") is True}
    if eligible:
        if bands:
            credit = marginal_credit(sum(eligible.values(), ZERO),
                                     [Band(number(b.get("lower_eur")) or 0, number(b.get("upper_eur")),
                                           number(b.get("percent")) or 0) for b in bands])
            for p, share in allocate_cents(credit, eligible).items():
                built[p].project_bonus = share
        else:
            for p in eligible:
                unknown_fields[p].add("rebate_total")

    # discount (rules 5, 16): the approved percentage, conditional on the undiscounted net of the bid
    net = undiscounted_net([(f.pieces, f.base_unit_price) for f in built.values()])
    percent = order_discount(number(discount.get("percent")) or 0, number(discount.get("threshold")), net, "bid")

    notes = "; ".join(f"{p} omitted: {why}" for p, why in sorted(skipped.items()))
    result = answer(Bid(tender_reference=reference, decision="bid", discount_percent=percent,
                        positions=[built[p] for p in sorted(built)], notes=notes[:3900]))
    for entry in result["positions"]:
        for field in unknown_fields.get(entry["position"], ()):
            entry.pop(field, None)        # blank = unanswered, better than a wrong 0
    return result

