"""The guard asks Clef first for items without input fields and the chat model only when Clef is unsure (fake Clef
endpoint, invented page items)."""
import asyncio
import json
import os
import unittest
from types import SimpleNamespace as NS
from unittest import mock

import httpx

from swarm import decide, guard


class FakeLLM:
    def __init__(self):
        self.calls = 0

    async def ask_json(self, system, user):
        self.calls += 1
        items = json.loads(user)["items"]
        return {"items": [{"id": i["id"], "action": "leave", "kind": "content"} for i in items]}


def clef(kind, kind_p, button, button_p=0.95):
    def handler(request):
        return httpx.Response(200, json={"answers": {"kind": {"choice": kind, "confidence": kind_p},
                                                      "button": {"choice": button, "confidence": button_p}}})
    return httpx.MockTransport(handler)


ITEM = {"id": 0, "kind": "overlay", "text": "Wartungshinweis: einige Funktionen werden gewartet",
        "buttons": [{"i": 0, "label": "Akzeptieren und fortfahren", "away": True}, {"i": 1, "label": "×", "away": False}],
        "fields": []}


class GuardClef(unittest.TestCase):
    def setUp(self):
        guard._DECISIONS.clear()
        guard._PENDING.clear()

    def run_classify(self, transport):
        llm = FakeLLM()
        g = guard.PopupGuard(NS(llm=llm), "test")
        with mock.patch.object(guard, "CLEF_ON", True), mock.patch.object(decide, "_transport", transport), \
                mock.patch.dict(os.environ, {"CLEF_BASE_URL": "http://clef", "CLEF_API_KEY": "k"}):
            asyncio.run(g._classify("site", [(("site", "sig"), dict(ITEM))]))
        return llm, guard._DECISIONS.get(("site", "sig"))

    def test_a_sure_clef_answer_decides_without_the_chat_model(self):
        llm, decision = self.run_classify(clef("notice", 0.93, "1"))
        self.assertEqual(llm.calls, 0)
        self.assertEqual((decision["action"], decision["kind"], decision["button"]), ("click", "notice", 1))

    def test_an_unsure_clef_answer_goes_to_the_chat_model(self):
        llm, decision = self.run_classify(clef("notice", 0.5, "1"))
        self.assertEqual(llm.calls, 1)
        self.assertEqual(decision["action"], "leave")

    def test_clef_choosing_an_away_link_falls_back_to_the_close_button(self):
        llm, decision = self.run_classify(clef("notice", 0.95, "0"))
        self.assertEqual(guard.pick_button(decision, ITEM), 1)           # the decoy link is never pressed

    def test_clef_down_means_the_chat_model_decides(self):
        llm, decision = self.run_classify(httpx.MockTransport(lambda r: httpx.Response(503)))
        self.assertEqual(llm.calls, 1)


if __name__ == "__main__":
    unittest.main()
