        text = json.dumps({"action": [{"click": {"index": 1}}, {"action": {"done": {"text": "t"}}}]})
        self.assertEqual(json.loads(normalize_actions(text))["action"], [{"click": {"index": 1}}, {"done": {"text": "t"}}])


